async page => {
 const root='http://127.0.0.1:18769/';
 const roles=['better-accessibility','better-colors','better-layout','better-typography','better-writing','better-ui','better-interface'];
 const out={tool:'Playwright CLI',session:'domain-fixture-smoke',started:new Date().toISOString(),browser:await page.context().browser().version(),cases:[]};
 async function read(){return await page.evaluate(()=>({title:document.title,width:innerWidth,scrollWidth:document.documentElement.scrollWidth,active:document.activeElement.id||document.activeElement.tagName}));}
 async function state(){return {snapshot:await page.locator('body').ariaSnapshot(),...await read()};}
 for(const role of roles)for(let n=1;n<=3;n++){
  const id=role+'-0'+n; const entry={id,errors:[],layouts:[],observations:{}};
  const listener=e=>entry.errors.push(e.message);page.on('pageerror',listener);
  await page.emulateMedia({reducedMotion:'no-preference',colorScheme:'light'});
  await page.setViewportSize({width:1280,height:800});await page.goto(root+id+'/app/');entry.initial=await state();
  for(const width of [1280,768,320]){await page.setViewportSize({width,height:800});entry.layouts.push(await read());}
  await page.setViewportSize({width:1280,height:800});
  if(id==='better-accessibility-01'){
   await page.locator('#email').focus();entry.observations.emailFocus=await page.locator('#email').evaluate(e=>({labels:e.labels.length,outline:getComputedStyle(e).outline,boxShadow:getComputedStyle(e).boxShadow}));
   await page.keyboard.press('Tab');entry.observations.afterEmailTab=await read();
   await page.locator('#send').click();entry.observations.validation=await state();
  }
  if(id==='better-accessibility-02'||id==='better-interface-02'){
   await page.locator('#send').focus();await page.keyboard.press('Enter');await page.keyboard.press('Enter');entry.observations.pending=await state();await page.waitForTimeout(800);entry.observations.afterRepeat=await state();
   if(id==='better-accessibility-02'){
    await page.locator('#remove').focus();await page.keyboard.press('Enter');entry.observations.afterRemove=await read();await page.keyboard.press('Tab');entry.observations.nextTab=await read();
    await page.locator('#details').focus();await page.keyboard.press('Enter');entry.observations.dialogOpen=await read();await page.keyboard.press('Escape');entry.observations.afterEscape=await page.locator('#modal').evaluate(e=>({hidden:e.hidden,active:document.activeElement.id}));
   }else{
    await page.locator('#name').fill('review');await page.locator('#send').click();await page.waitForTimeout(800);entry.observations.error=await state();
    await page.emulateMedia({reducedMotion:'reduce'});await page.locator('#preview-button').click();entry.observations.reducedAnimation=await page.locator('#preview').evaluate(e=>({animation:getComputedStyle(e).animationName,text:e.textContent}));
   }
  }
  if(id==='better-accessibility-03'||id==='better-interface-03'){
   await page.locator('#send').click();entry.observations.validation=await state();await page.locator('#email').fill('min@example.com');await page.locator('#send').focus();await page.keyboard.press('Enter');await page.keyboard.press('Enter');entry.observations.pending=await state();await page.waitForTimeout(700);entry.observations.success=await state();
   await page.locator('#details').focus();await page.keyboard.press('Enter');entry.observations.dialogOpen=await read();await page.keyboard.press('Escape');entry.observations.dialogEscape=await page.locator('#dialog').evaluate(e=>({open:e.open,active:document.activeElement.id}));
  }
  if(role==='better-colors'){
   const pairs=async()=>await page.evaluate(()=>Array.from(document.querySelectorAll('p,button,input,.badge')).map(e=>{const s=getComputedStyle(e);let a=e;while(a&&getComputedStyle(a).backgroundColor==='rgba(0, 0, 0, 0)')a=a.parentElement;return {id:e.id,text:e.textContent.slice(0,80),foreground:s.color,background:a?getComputedStyle(a).backgroundColor:null,border:s.borderColor,font:s.fontSize,disabled:e.disabled||false};}));
   entry.observations.light=pairs?await pairs():null;
   if(n>1){await page.locator('#theme').click();entry.observations.dark=await pairs();}
  }
  if(id==='better-layout-01'){
   await page.setViewportSize({width:320,height:568});entry.observations.actionBounds=await page.locator('#open').boundingBox();entry.observations.rail=await page.locator('.rail').evaluate(e=>({clientWidth:e.clientWidth,scrollWidth:e.scrollWidth,scrollbar:getComputedStyle(e).scrollbarWidth}));await page.screenshot({path:'/tmp/domain-fixture-smoke/layout01-320.png'});
  }
  if(id==='better-layout-02'){
   await page.setViewportSize({width:320,height:568});await page.locator('#open').click();entry.observations.dialog=await page.locator('#dialog').boundingBox();entry.observations.confirm=await page.locator('#confirm').boundingBox();await page.screenshot({path:'/tmp/domain-fixture-smoke/layout02-dialog.png'});await page.keyboard.press('Escape');await page.locator('#direction').click();entry.observations.rtl=await page.locator('.event').evaluate(e=>({dir:document.documentElement.dir,paddingRight:getComputedStyle(e).paddingRight,text:e.firstElementChild.getBoundingClientRect().toJSON(),tag:e.lastElementChild.getBoundingClientRect().toJSON()}));
  }
  if(id==='better-layout-03'){
   await page.setViewportSize({width:320,height:568});entry.observations.table=await page.locator('.table-scroll').evaluate(e=>({clientWidth:e.clientWidth,scrollWidth:e.scrollWidth,pageWidth:document.documentElement.scrollWidth}));await page.locator('#direction').click();entry.observations.rtl=await state();
  }
  if(role==='better-typography'){
   await page.setViewportSize({width:320,height:568});entry.observations.type=await page.evaluate(()=>Array.from(document.querySelectorAll('h1,h2,p,input,output')).map(e=>{let s=getComputedStyle(e);return {id:e.id,tag:e.tagName,text:e.textContent.slice(0,80),size:s.fontSize,weight:s.fontWeight,lineHeight:s.lineHeight,variant:s.fontVariantNumeric,select:s.userSelect,clientWidth:e.clientWidth,scrollWidth:e.scrollWidth};}));
  }
  if(id==='better-writing-01'){
   await page.locator('#save').click();entry.observations.afterSave=await state();await page.locator('#sync').click();entry.observations.error=await state();
  }
  if(id==='better-writing-02'){
   await page.locator('#query').fill('missing');entry.observations.empty=await state();await page.locator('#query').fill('');await page.locator('#remove').click();entry.observations.dialog=await state();await page.locator('#confirm').click();entry.observations.afterDelete=await state();
  }
  if(id==='better-writing-03'){
   await page.locator('#archive').click();entry.observations.archive=await state();await page.locator('#undo').click();entry.observations.undo=await state();await page.locator('#form button').click();entry.observations.error=await state();await page.locator('#name').fill('Mina');await page.locator('#form button').click();entry.observations.success=await state();
  }
  if(id==='better-ui-01'){
   await page.emulateMedia({reducedMotion:'reduce'});await page.locator('#bookmark').hover();await page.waitForTimeout(450);entry.observations.reduced=await page.locator('#bookmark').evaluate(e=>({transform:getComputedStyle(e).transform,transition:getComputedStyle(e).transition}));await page.locator('#bookmark').click();entry.observations.selected=await page.locator('#bookmark').evaluate(e=>({textColor:getComputedStyle(e).color,stroke:getComputedStyle(e.querySelector('svg')).stroke}));
  }
  if(id==='better-ui-02'){
   await page.locator('#toggle').click();await page.waitForTimeout(250);entry.observations.during=await page.locator('#drawer').evaluate(e=>getComputedStyle(e).transform);await page.locator('#toggle').click();entry.observations.reversed=await page.locator('#drawer').evaluate(e=>getComputedStyle(e).transform);
   await page.emulateMedia({reducedMotion:'reduce'});await page.locator('#toggle').click();entry.observations.reduced=await page.locator('#drawer').evaluate(e=>({animation:getComputedStyle(e).animationName,overscroll:getComputedStyle(e.querySelector('.scroll')).overscrollBehavior}));
   await page.locator('#theme').click();entry.observations.theme=await page.locator('body').evaluate(e=>({transition:getComputedStyle(e).transition,animations:e.getAnimations().length}));
  }
  if(id==='better-ui-03'){
   await page.emulateMedia({reducedMotion:'reduce'});await page.locator('#saved').click();await page.locator('#mark').click();entry.observations.reduced=await state();
  }
  if(id==='better-interface-01'){
   await page.locator('#delete').click();entry.observations.deleted=await state();
  }
  page.off('pageerror',listener);out.cases.push(entry);
 }
 out.finished=new Date().toISOString();return out;
}
